import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.rQcsxYkC.js";const u=JSON.parse('{"title":"Connecting a wallet","description":"","frontmatter":{},"headers":[],"relativePath":"guide/connecting-a-wallet.md","filePath":"guide/connecting-a-wallet.md","lastUpdated":1785888355000}'),s={name:"guide/connecting-a-wallet.md"};function r(i,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="connecting-a-wallet" tabindex="-1">Connecting a wallet <a class="header-anchor" href="#connecting-a-wallet" aria-label="Permalink to &quot;Connecting a wallet&quot;">​</a></h1><p>Arc Names runs on Arc Testnet. Your wallet needs to know that network exists, and it needs some gas to spend.</p><h2 id="network-details" tabindex="-1">Network details <a class="header-anchor" href="#network-details" aria-label="Permalink to &quot;Network details&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Network name</td><td>Arc Testnet</td></tr><tr><td>Chain ID</td><td><code>5042002</code> (<code>0x4cef52</code> in hex)</td></tr><tr><td>Currency symbol</td><td>USDC</td></tr><tr><td>Currency decimals</td><td><strong>18</strong></td></tr><tr><td>Block explorer</td><td><a href="https://testnet.arcscan.app" target="_blank" rel="noreferrer">https://testnet.arcscan.app</a></td></tr><tr><td>RPC URL</td><td>See <a href="#rpc-endpoints">below</a></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">The gas token has 18 decimals</p><p>Arc&#39;s native gas token is USDC, but as a <em>native</em> token it uses <strong>18 decimals</strong>, not the 6 decimals of the ERC-20 USDC you may be used to. If you configure a wallet by hand and enter 6, every balance and price you see will be wrong by a factor of a trillion.</p><p>The distinction matters on-chain too: the controller and the marketplace can settle in either the native token or the 6-decimal ERC-20, and they convert between the two. See <a href="/docs/protocol/fees.html#two-kinds-of-usdc">Fees</a>.</p></div><h2 id="connecting" tabindex="-1">Connecting <a class="header-anchor" href="#connecting" aria-label="Permalink to &quot;Connecting&quot;">​</a></h2><p>Press <strong>Connect</strong> in the app header. A wallet picker opens, listing the wallets you can use: browser extensions it detects as installed, plus Rainbow, Coinbase Wallet and <strong>WalletConnect</strong> for everything else. Pick one and approve the connection request in the wallet.</p><p>If you have no wallet at all, the picker&#39;s <strong>New to Ethereum wallets?</strong> link explains what a wallet is and where to get one.</p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Choose <strong>WalletConnect</strong>. On a phone browser this offers to open your wallet app directly; on a desktop browser it shows a QR code to scan with the wallet app on your phone. Either way the app and the wallet stay linked until you disconnect.</p><h2 id="adding-the-network" tabindex="-1">Adding the network <a class="header-anchor" href="#adding-the-network" aria-label="Permalink to &quot;Adding the network&quot;">​</a></h2><p><strong>The easy way.</strong> Connect first. If your wallet is on a different network, the header button reads <strong>Wrong network</strong> and a banner appears with a <strong>Switch network</strong> button. Press either — most wallets will offer to add Arc Testnet automatically.</p><p><strong>By hand.</strong> In MetaMask: <em>Settings → Networks → Add network → Add a network manually</em>, then enter the values from the table above. Other wallets have an equivalent screen. Take care with the decimals field.</p><h2 id="rpc-endpoints" tabindex="-1">RPC endpoints <a class="header-anchor" href="#rpc-endpoints" aria-label="Permalink to &quot;RPC endpoints&quot;">​</a></h2><p>A browser app can only use an RPC endpoint that returns CORS headers. This trips up more integrations than anything else on this page.</p><p>The public endpoint <code>https://rpc.testnet.arc.network</code> <strong>does not send CORS headers</strong>. It works perfectly from a server, a script, or <code>curl</code> — and fails from every browser tab, with an error that looks like a network outage rather than a configuration problem.</p><p>For a browser app, use a provider endpoint that sets CORS headers. The Arc Names app resolves its endpoint from environment configuration at build time:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .env — copy from .env.example</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Preferred: a provider key. The app builds the full URL from it.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VITE_ALCHEMY_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_key_here</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or override the whole URL, for a self-hosted or alternative endpoint.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># VITE_ARC_RPC_URL=https://your-endpoint.example/v2/xyz</span></span></code></pre></div><p>If neither is set, the app falls back to the public endpoint and logs a warning to the console explaining that every read will fail in the browser. That fallback exists so the app still builds without configuration — it is not a usable production setup.</p><div class="danger custom-block"><p class="custom-block-title">Any VITE_ variable is public</p><p>Vite compiles <code>VITE_*</code> environment variables into the JavaScript bundle it ships to the browser. Anyone who loads your app can read the key out of it. This is unavoidable for a client-side app — the browser has to know the URL it&#39;s calling.</p><p>Protect the key with a <strong>domain allowlist</strong> in your provider&#39;s dashboard, so it only works when called from your origin. Never put a key with billing or write authority in a <code>VITE_</code> variable.</p></div><h2 id="getting-testnet-gas" tabindex="-1">Getting testnet gas <a class="header-anchor" href="#getting-testnet-gas" aria-label="Permalink to &quot;Getting testnet gas&quot;">​</a></h2><p>You need native USDC on Arc Testnet to pay for gas and for registrations. Use the Arc Testnet faucet, then check the balance landed by looking your address up on <a href="https://testnet.arcscan.app" target="_blank" rel="noreferrer">testnet.arcscan.app</a>.</p><p>Testnet funds have no value. Nobody should ever ask you to buy them.</p><h2 id="which-wallets-work" tabindex="-1">Which wallets work <a class="header-anchor" href="#which-wallets-work" aria-label="Permalink to &quot;Which wallets work&quot;">​</a></h2><p>Any wallet that supports custom EVM networks and the standard browser injection or WalletConnect. The app is built on wagmi and viem, so browser-extension wallets, mobile wallets over WalletConnect, and hardware wallets behind either all work.</p><p>A hardware wallet is worth it for a name you care about. See <a href="/docs/safety.html#protecting-a-name-you-care-about">Safety</a>.</p><div class="tip custom-block"><p class="custom-block-title">Running your own copy?</p><p>WalletConnect needs a free project ID from <a href="https://cloud.reown.com" target="_blank" rel="noreferrer">Reown Cloud</a>. Set it as <code>VITE_WALLETCONNECT_PROJECT_ID</code> in <code>.env</code>. Without it the picker falls back to offering only installed browser extensions — which means no mobile path, so set it before deploying anywhere people will use a phone.</p></div><h2 id="checking-the-connection" tabindex="-1">Checking the connection <a class="header-anchor" href="#checking-the-connection" aria-label="Permalink to &quot;Checking the connection&quot;">​</a></h2><p>Once connected, the app header shows your address (or your <a href="/docs/guide/primary-name.html">primary name</a>, if you&#39;ve set one). An amber warning triangle next to it means a name points back at your address but the name&#39;s own record doesn&#39;t confirm it — so the app shows your address instead. See <a href="/docs/guide/primary-name.html">Primary name</a>.</p><p>If something is wrong, a banner appears under the header:</p><table tabindex="0"><thead><tr><th>Banner</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Wrong network</strong></td><td>Your wallet is connected to a different chain. Press switch.</td></tr><tr><td><strong>Can&#39;t reach the Arc network</strong></td><td>The RPC endpoint is unreachable — see <a href="#rpc-endpoints">RPC endpoints</a>.</td></tr><tr><td><strong>Data may be out of date</strong></td><td>The indexer is behind the chain. On-chain reads are still correct; listings and activity may lag. See <a href="/docs/api/endpoints.html#sync-status">API endpoints</a>.</td></tr></tbody></table><h2 id="disconnecting" tabindex="-1">Disconnecting <a class="header-anchor" href="#disconnecting" aria-label="Permalink to &quot;Disconnecting&quot;">​</a></h2><p>Press your address (or name) in the header to open the account panel, then choose <strong>Disconnect</strong>. This only ends the app&#39;s session — it does not move, lock, or affect your names in any way. Your names live in the wallet, not in the app.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/guide/quick-start.html">Quick start</a> — register your first name.</li><li><a href="/docs/safety.html">Safety &amp; cautions</a> — read this before signing anything.</li></ul>`,35)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
